test("paste claims scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "7");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33", "from": "2026-03-01"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "20.00", "date": "2026-03-28"}));
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-09", "to": "2026-03-28"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  const c_dot_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Dot", "amount": "0.04"}));
  const p_dot = await ui.personId(pg_uma, "Dot");
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-02-25", "to": "2026-03-15"})).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_cam_0, "settle")).toBe(true);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("20.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("4.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("4.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("SETTLED");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("person-row-" + p_dot).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_dot).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-due")).toHaveText("0.50");
  await expect(pg_vic.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_vic.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("20.00");
  await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("4.00");
  await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("header-people-count")).toHaveText("4");
  await expect(pg_vic.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-SETTLED-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-due-total")).toHaveText("4.00");
  await expect(pg_vic.getByTestId("header-overdue-total")).toHaveText("0.00");
  expect(await ui.setSettingDated(pg_vic, "floor", "3.00", "2026-03-09", "0.50")).toBe(true);
  expect(await ui.hold(pg_vic, p_cam, {"from": "2026-03-09", "to": "2026-03-15"})).toBe(true);
  expect(await ui.editPerson(pg_vic, p_cam, {"grade": "C", "gradeFrom": "2026-02-10"})).toBe(true);
  expect(await ui.claimAction(pg_vic, c_dot_0, "open")).toBe(true);
  const c_cam_1 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "10.35"}));
  expect(await ui.hold(pg_vic, p_ben, {"from": "2026-02-25", "to": "2026-03-09"})).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.reassign(pg_vic, c_cam_1, "Dot")).toBe(true);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("20.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("4.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("4.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("SETTLED");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("person-row-" + p_dot).getByTestId("person-claimed")).toHaveText("0.04");
  await expect(pg_vic.getByTestId("person-row-" + p_dot).getByTestId("person-due-total")).toHaveText("0.50");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.29");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-due")).toHaveText("0.50");
  await expect(pg_vic.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_vic.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("20.04");
  await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("4.50");
  await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("header-people-count")).toHaveText("4");
  await expect(pg_vic.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-OPEN-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-SETTLED-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-due-total")).toHaveText("4.50");
  await expect(pg_vic.getByTestId("header-overdue-total")).toHaveText("0.00");
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_dot_0, "settle")).toBe(true);
  expect(await ui.pasteClaims(pg_uma, "Dot,99.95,2026-04-02,a, b")).toBe(1);
  const c_dot_2 = await ui.claimAt(pg_uma, p_dot, 2);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.setRate(pg_wes, {"grade": "B", "pct": "5.00"})).toBe(true);
  const c_cam_1_2 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "-10.25", "corrects": "1"}));
  const c_ben_0 = ui.must(await ui.addClaim(pg_wes, p_ben, {"amount": "25.00", "date": "2026-03-09"}));
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("5.00");

