package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Refuse a new claim dated (a blank date being the sheet's today) after its person's retirement date. */
public class RefuseRetiredNewClaim {
    public void refuse(@Val ClaimInput input, @Val Person person, SheetRepository sheets) throws RetiredPersonException {
        RetiredPersonException.refuse(person, input.date() != null ? input.date() : sheets.today(person.sheetId()));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Refuse a new claim dated (a blank date being the sheet's today) inside a closed period. */
public class RefuseClosedNewClaim {
    public void refuse(@Val ClaimInput input, @Val Person person, SheetRepository sheets, PeriodRepository periods)
            throws ClosedPeriodException {
        periods.lockSheet(person.sheetId());
        var date = input.date() != null ? input.date() : sheets.today(person.sheetId());
        Period closed = periods.closedOn(person.sheetId(), date);
        if (closed != null) {
            throw new ClosedPeriodException(closed);
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Refuse a new correction unless the number it names is a SETTLED claim of the same person. */
public class RefuseInvalidNewCorrection {
    public void refuse(@Val ClaimInput input, @Val Person person, ClaimRepository repository)
            throws InvalidClaimException {
        if (input.corrects() != null && !repository.settledNumbered(person.sheetId(), person.id(), input.corrects())) {
            throw new InvalidClaimException("A correction must name a SETTLED claim of the same person; "
                    + person.name() + " has no SETTLED claim " + input.corrects() + ".");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Store the new claim under the person; with no date given it is dated the sheet's today. Its due-by is fixed now:
 *  its date plus the terms of the person's grade in force on its date (else the sheet's terms in force on its date). Its DRAFT line starts its status log. */
public class SaveNewClaim {
    public void save(@Val ClaimInput input, @Val Person person, SheetRepository sheets, SettingRepository settings,
            ClaimRepository repository, ClaimLogRepository log, Out<Claim> claim) {
        var date = input.date() != null ? input.date() : sheets.today(person.sheetId());
        var dueBy = date.plusDays(settings.termsFor(person.sheetId(), person.grades().on(date), date));
        Claim added = repository.insert(new Claim(0, person.sheetId(), person.id(), input.amount(), date, input.note(),
                ClaimStatus.DRAFT, null, null, null, false, null, input.corrects(), dueBy));
        log.record(added, input.user());
        claim.set(added);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Record the stored add in the audit file, with the amount and date as the screen shows them. */
public class AuditClaimAdded {
    public void audit(@Val ClaimInput input, @Val Person person, @Val Claim claim, Audit audit) {
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + input.user()
                + " person=" + person.name() + " amount=" + shown.amount() + " date=" + shown.date());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class RespondWithClaimCreated {
    public void respond(@Val Claim claim, ObjectResponse<ResponseEntity<ClaimResponse>> response) {
        response.send(new ResponseEntity<>(ClaimResponse.from(claim), HttpStatus.CREATED));
    }
}

